import { useEffect, useMemo, useState } from "react";
import {
  Box,
  Button,
  CircularProgress,
  Container,
  MenuItem,
  Select,
  TextField,
  Typography,
  Grid,
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";
import { useTheme } from "../ThemeContext";
import { getAiReply } from "../utils/ai";
import { CryptoState } from "../CryptoContext";

const clamp = (value, min, max) => Math.min(Math.max(value, min), max);

const numberWithCommas = (value) =>
  Number(value).toLocaleString(undefined, { maximumFractionDigits: 2 });

const getCoinScore = (coin) => {
  const momentum = clamp((coin.price_change_percentage_24h || 0) / 15, -1, 1);
  const liquidityRaw = coin.market_cap
    ? coin.total_volume / coin.market_cap
    : 0;
  const liquidity = clamp(liquidityRaw / 0.25, 0, 1);
  const size = 1 - clamp((coin.market_cap_rank || 100) / 100, 0, 1);

  const score = momentum * 0.5 + liquidity * 0.2 + size * 0.3;
  return Number(score.toFixed(4));
};

const getSummary = (coin, symbol) => {
  const price = coin.current_price != null ? `${symbol}${numberWithCommas(coin.current_price)}` : "N/A";
  const marketCap = coin.market_cap != null ? `${symbol}${numberWithCommas(coin.market_cap)}` : "N/A";
  const dayChange = coin.price_change_percentage_24h != null ? `${coin.price_change_percentage_24h.toFixed(2)}%` : "N/A";
  const high24 = coin.high_24h != null ? `${symbol}${numberWithCommas(coin.high_24h)}` : "N/A";
  const low24 = coin.low_24h != null ? `${symbol}${numberWithCommas(coin.low_24h)}` : "N/A";

  return `${coin.name} (${coin.symbol.toUpperCase()}) is currently trading at ${price}. In the last 24 hours it moved ${dayChange}, with a daily range between ${low24} and ${high24}. Its market cap is ${marketCap} and rank is #${coin.market_cap_rank || "N/A"}. This snapshot suggests ${coin.price_change_percentage_24h >= 0 ? "short-term positive momentum" : "short-term weakness"}, so manage risk and avoid all-in entries.`;
};

const useStyles = makeStyles((theme) => ({
  container: {
    paddingTop: theme.spacing(6),
    paddingBottom: theme.spacing(8),
    minHeight: "85vh",
    fontFamily: "'Montserrat', 'Inter', sans-serif",
  },
  header: {
    fontWeight: 800,
    marginBottom: theme.spacing(1),
    background: "-webkit-linear-gradient(45deg, #e6c200 10%, #FFD700 90%)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    letterSpacing: "1px",
    textTransform: "uppercase",
  },
  headerLight: {
    fontWeight: 800,
    marginBottom: theme.spacing(1),
    background: "-webkit-linear-gradient(45deg, #d4af37 10%, #b8860b 90%)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    letterSpacing: "1px",
    textTransform: "uppercase",
  },
  subtitle: {
    marginBottom: theme.spacing(5),
    fontWeight: 500,
    opacity: 0.8,
  },
  glassCard: {
    backdropFilter: "blur(12px)",
    backgroundColor: "rgba(25, 25, 25, 0.65)",
    border: "1px solid rgba(255, 255, 255, 0.08)",
    borderRadius: 20,
    padding: theme.spacing(4),
    boxShadow: "0 8px 32px 0 rgba(0, 0, 0, 0.4)",
    transition: "transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.4s ease",
    "&:hover": {
      transform: "translateY(-6px)",
      boxShadow: "0 15px 40px 0 rgba(0, 0, 0, 0.5)",
      border: "1px solid rgba(255, 215, 0, 0.2)",
    },
    height: "100%",
    display: "flex",
    flexDirection: "column",
  },
  glassCardLight: {
    backdropFilter: "blur(12px)",
    backgroundColor: "rgba(255, 255, 255, 0.75)",
    border: "1px solid rgba(0, 0, 0, 0.05)",
    borderRadius: 20,
    padding: theme.spacing(4),
    boxShadow: "0 8px 32px 0 rgba(31, 38, 135, 0.07)",
    transition: "transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.4s ease",
    "&:hover": {
      transform: "translateY(-6px)",
      boxShadow: "0 15px 40px 0 rgba(31, 38, 135, 0.12)",
      border: "1px solid rgba(212, 175, 55, 0.3)",
    },
    height: "100%",
    display: "flex",
    flexDirection: "column",
  },
  cardTitle: {
    fontWeight: 700,
    marginBottom: theme.spacing(2),
    fontSize: "1.25rem",
    color: "#FFD700",
  },
  cardTitleLight: {
    fontWeight: 700,
    marginBottom: theme.spacing(2),
    fontSize: "1.25rem",
    color: "#b8860b",
  },
  actionButton: {
    background: "linear-gradient(45deg, #FFD700 30%, #FFA500 90%)",
    border: 0,
    borderRadius: 12,
    boxShadow: "0 4px 15px 0 rgba(255, 215, 0, 0.3)",
    color: "#111",
    height: 48,
    padding: "0 30px",
    fontWeight: 700,
    marginTop: theme.spacing(2),
    transition: "all 0.3s ease",
    "&:hover": {
      boxShadow: "0 6px 20px 0 rgba(255, 215, 0, 0.5)",
      transform: "scale(1.03)",
      background: "linear-gradient(45deg, #FFA500 30%, #FFD700 90%)",
    },
    "&:disabled": {
      background: "rgba(100, 100, 100, 0.5)",
      color: "rgba(255, 255, 255, 0.3)",
    }
  },
  actionButtonLight: {
    background: "linear-gradient(45deg, #d4af37 30%, #ffd700 90%)",
    border: 0,
    borderRadius: 12,
    boxShadow: "0 4px 15px 0 rgba(212, 175, 55, 0.3)",
    color: "#fff",
    height: 48,
    padding: "0 30px",
    fontWeight: 700,
    marginTop: theme.spacing(2),
    transition: "all 0.3s ease",
    "&:hover": {
      boxShadow: "0 6px 20px 0 rgba(212, 175, 55, 0.5)",
      transform: "scale(1.03)",
    },
    "&:disabled": {
      background: "rgba(0, 0, 0, 0.1)",
      color: "rgba(0, 0, 0, 0.3)",
    }
  },
  actionButtonSecondary: {
    background: "transparent",
    border: "2px solid #FFD700",
    borderRadius: 12,
    color: "#FFD700",
    height: 48,
    padding: "0 30px",
    fontWeight: 700,
    marginTop: theme.spacing(2),
    transition: "all 0.3s ease",
    "&:hover": {
      background: "rgba(255, 215, 0, 0.1)",
      boxShadow: "0 0 15px rgba(255, 215, 0, 0.2)",
    },
  },
  actionButtonSecondaryLight: {
    background: "transparent",
    border: "2px solid #d4af37",
    borderRadius: 12,
    color: "#d4af37",
    height: 48,
    padding: "0 30px",
    fontWeight: 700,
    marginTop: theme.spacing(2),
    transition: "all 0.3s ease",
    "&:hover": {
      background: "rgba(212, 175, 55, 0.05)",
      boxShadow: "0 0 15px rgba(212, 175, 55, 0.15)",
    },
  },
  resultArea: {
    marginTop: theme.spacing(3),
    flexGrow: 1,
    padding: theme.spacing(2.5),
    borderRadius: 12,
    backgroundColor: "rgba(0,0,0,0.3)",
    border: "1px solid rgba(255, 255, 255, 0.05)",
    fontFamily: "'Inter', sans-serif",
    fontSize: "0.95rem",
    lineHeight: 1.6,
    color: "rgba(255, 255, 255, 0.85)",
  },
  resultAreaLight: {
    marginTop: theme.spacing(3),
    flexGrow: 1,
    padding: theme.spacing(2.5),
    borderRadius: 12,
    backgroundColor: "rgba(0,0,0,0.03)",
    border: "1px solid rgba(0, 0, 0, 0.05)",
    fontFamily: "'Inter', sans-serif",
    fontSize: "0.95rem",
    lineHeight: 1.6,
    color: "rgba(0, 0, 0, 0.8)",
  },
  textField: {
    "& .MuiOutlinedInput-root": {
      borderRadius: 12,
      fontFamily: "'Inter', sans-serif",
      backgroundColor: "rgba(0,0,0,0.2)",
      "& fieldset": {
        borderColor: "rgba(255, 255, 255, 0.2)",
      },
      "&:hover fieldset": {
        borderColor: "rgba(255, 215, 0, 0.5)",
      },
      "&.Mui-focused fieldset": {
        borderColor: "#FFD700",
      },
    },
    "& .MuiInputBase-input": {
      color: "#fff",
    },
    "& .MuiInputLabel-root": {
      color: "rgba(255,255,255,0.7)",
    },
  },
  textFieldLight: {
    "& .MuiOutlinedInput-root": {
      borderRadius: 12,
      fontFamily: "'Inter', sans-serif",
      backgroundColor: "rgba(255,255,255,0.5)",
      "& fieldset": {
        borderColor: "rgba(0, 0, 0, 0.2)",
      },
      "&:hover fieldset": {
        borderColor: "rgba(212, 175, 55, 0.5)",
      },
      "&.Mui-focused fieldset": {
        borderColor: "#d4af37",
      },
    },
    "& .MuiInputBase-input": {
      color: "#111",
    },
    "& .MuiInputLabel-root": {
      color: "rgba(0,0,0,0.6)",
    },
  },
  selectRoot: {
    borderRadius: 12,
    backgroundColor: "rgba(0,0,0,0.2)",
    "& .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(255, 255, 255, 0.2)",
    },
    "&:hover .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(255, 215, 0, 0.5)",
    },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
      borderColor: "#FFD700",
    },
  },
  selectRootLight: {
    borderRadius: 12,
    backgroundColor: "rgba(255,255,255,0.5)",
    "& .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(0, 0, 0, 0.2)",
    },
    "&:hover .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(212, 175, 55, 0.5)",
    },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
      borderColor: "#d4af37",
    },
  },
  chatResponse: {
    marginTop: theme.spacing(5),
    padding: theme.spacing(4),
    borderRadius: 20,
    backgroundColor: "rgba(20, 20, 20, 0.7)",
    backdropFilter: "blur(15px)",
    borderLeft: "5px solid #FFD700",
    boxShadow: "0 10px 40px rgba(0,0,0,0.4)",
    animation: "$fadeInUp 0.6s cubic-bezier(0.165, 0.84, 0.44, 1)",
    border: "1px solid rgba(255,255,255,0.05)",
  },
  chatResponseLight: {
    marginTop: theme.spacing(5),
    padding: theme.spacing(4),
    borderRadius: 20,
    backgroundColor: "rgba(255, 255, 255, 0.95)",
    backdropFilter: "blur(15px)",
    borderLeft: "5px solid #d4af37",
    boxShadow: "0 10px 40px rgba(31, 38, 135, 0.08)",
    animation: "$fadeInUp 0.6s cubic-bezier(0.165, 0.84, 0.44, 1)",
    border: "1px solid rgba(0,0,0,0.03)",
  },
  "@keyframes fadeInUp": {
    from: { opacity: 0, transform: "translateY(20px)" },
    to: { opacity: 1, transform: "translateY(0)" },
  },
}));

const AiPage = () => {
  const { isDarkMode } = useTheme();
  const classes = useStyles();
  const { coins, fetchCoins, loading: coinsLoading, symbol } = CryptoState();
  const [prompt, setPrompt] = useState("");
  const [reply, setReply] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [error, setError] = useState("");
  const [selectedCoinId, setSelectedCoinId] = useState("");
  const [coinSummary, setCoinSummary] = useState("");
  const [recommendation, setRecommendation] = useState("");

  useEffect(() => {
    if (!coins.length) {
      fetchCoins();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const selectedCoin = useMemo(
    () => coins.find((coin) => coin.id === selectedCoinId),
    [coins, selectedCoinId]
  );

  const onAskAi = async () => {
    const cleanedPrompt = prompt.trim();
    if (!cleanedPrompt) return;

    setAiLoading(true);
    setError("");
    try {
      const result = await getAiReply(cleanedPrompt, "gemini");
      setReply(result);
    } catch (err) {
      setError(err.message || "Unable to fetch AI response.");
    } finally {
      setAiLoading(false);
    }
  };

  const onRecommend = () => {
    if (!coins.length) {
      setRecommendation("No coin data is available yet. Please wait and try again.");
      return;
    }

    const ranked = [...coins]
      .filter((coin) => coin.market_cap_rank && coin.market_cap_rank <= 50)
      .map((coin) => ({ ...coin, score: getCoinScore(coin) }))
      .sort((a, b) => b.score - a.score);

    const pick = ranked[0];
    if (!pick) {
      setRecommendation("Unable to generate recommendation from current data.");
      return;
    }

    const confidence = clamp(((pick.score + 1) / 2) * 100, 0, 100).toFixed(0);
    setRecommendation(
      `Suggested buy candidate: ${pick.name} (${pick.symbol.toUpperCase()}). Confidence: ${confidence}% based on momentum, liquidity, and market-cap rank from the latest snapshot. Current price: ${symbol}${numberWithCommas(pick.current_price)}. 24h move: ${pick.price_change_percentage_24h?.toFixed(2)}%.`
    );
  };

  const onGenerateSummary = () => {
    if (!selectedCoin) {
      setCoinSummary("Select a coin to generate a summary.");
      return;
    }
    setCoinSummary(getSummary(selectedCoin, symbol));
  };

  return (
    <Container className={classes.container}>
      <Box mb={2}>
        <Typography variant="h3" className={isDarkMode ? classes.header : classes.headerLight}>
          Rubina <span style={{ fontWeight: 300 }}>AI</span>
        </Typography>
        <Typography variant="subtitle1" className={classes.subtitle} style={{ color: isDarkMode ? "#aaa" : "#555" }}>
          Unleash data-driven crypto insights with our premium AI assistant.
        </Typography>
      </Box>

      <Grid container spacing={4}>
        <Grid item xs={12} md={6}>
          <Box className={isDarkMode ? classes.glassCard : classes.glassCardLight}>
            <Typography variant="h6" className={isDarkMode ? classes.cardTitle : classes.cardTitleLight}>
              Smart Buy Suggestion
            </Typography>
            <Typography variant="body2" style={{ color: isDarkMode ? "#bbb" : "#666", marginBottom: 16 }}>
              Our algorithm ranks the top 50 coins based on momentum, liquidity, and market cap to find the best short-term candidate.
            </Typography>

            <Button
              variant="contained"
              onClick={onRecommend}
              disabled={coinsLoading}
              className={isDarkMode ? classes.actionButton : classes.actionButtonLight}
              fullWidth
            >
              Predict Best Coin to Buy
            </Button>

            <Box className={isDarkMode ? classes.resultArea : classes.resultAreaLight}>
              {recommendation || "Click above to analyze the live market data."}
            </Box>
            <Typography variant="caption" style={{ color: isDarkMode ? "rgba(255,255,255,0.4)" : "rgba(0,0,0,0.4)", marginTop: 12, textAlign: "center" }}>
              This is a model-driven estimate, not financial advice.
            </Typography>
          </Box>
        </Grid>

        <Grid item xs={12} md={6}>
          <Box className={isDarkMode ? classes.glassCard : classes.glassCardLight}>
            <Typography variant="h6" className={isDarkMode ? classes.cardTitle : classes.cardTitleLight}>
              Instant Coin Summary
            </Typography>
            <Typography variant="body2" style={{ color: isDarkMode ? "#bbb" : "#666", marginBottom: 16 }}>
              Select any cryptocurrency from the market to generate a quick, digestible snapshot of its current performance.
            </Typography>

            <Select
              value={selectedCoinId}
              onChange={(e) => setSelectedCoinId(e.target.value)}
              displayEmpty
              variant="outlined"
              fullWidth
              className={isDarkMode ? classes.selectRoot : classes.selectRootLight}
              style={{ color: isDarkMode ? "#fff" : "#111" }}
            >
              <MenuItem value=""><em>Select a cryptocurrency</em></MenuItem>
              {coins.slice(0, 100).map((coin) => (
                <MenuItem key={coin.id} value={coin.id}>
                  {coin.name} ({coin.symbol.toUpperCase()})
                </MenuItem>
              ))}
            </Select>

            <Button
              variant="outlined"
              onClick={onGenerateSummary}
              className={isDarkMode ? classes.actionButtonSecondary : classes.actionButtonSecondaryLight}
              fullWidth
            >
              Generate Summary
            </Button>

            <Box className={isDarkMode ? classes.resultArea : classes.resultAreaLight}>
              {coinSummary || "Choose a coin to see its performance snapshot."}
            </Box>
          </Box>
        </Grid>

        <Grid item xs={12}>
          <Box className={isDarkMode ? classes.glassCard : classes.glassCardLight} style={{ marginTop: 8 }}>
            <Typography variant="h6" className={isDarkMode ? classes.cardTitle : classes.cardTitleLight}>
              Chat with Rubina
            </Typography>
            <Typography variant="body2" style={{ color: isDarkMode ? "#bbb" : "#666", marginBottom: 20 }}>
              Ask anything about crypto. Rubina runs on the latest Gemini models to give you instant, reliable answers.
            </Typography>

            <TextField
              placeholder="E.g., What is Bitcoin halving?"
              variant="outlined"
              fullWidth
              multiline
              rows={4}
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              className={isDarkMode ? classes.textField : classes.textFieldLight}
            />

            <Box style={{ marginTop: 24, display: "flex", gap: 16, alignItems: "center" }}>
              <Button
                variant="contained"
                onClick={onAskAi}
                disabled={aiLoading || !prompt.trim()}
                className={isDarkMode ? classes.actionButton : classes.actionButtonLight}
                style={{ width: "200px" }}
              >
                Ask Rubina
              </Button>
              {aiLoading && <CircularProgress size={28} style={{ color: isDarkMode ? "#FFD700" : "#d4af37" }} />}
            </Box>

            {error && (
              <Typography style={{ marginTop: 16, color: "#ff4d4d", fontWeight: 600, padding: "8px 12px", background: "rgba(255,77,77,0.1)", borderRadius: 8 }}>
                {error}
              </Typography>
            )}
          </Box>
        </Grid>
      </Grid>

      {reply && (
        <Box className={isDarkMode ? classes.chatResponse : classes.chatResponseLight}>
          <Typography variant="h6" style={{ fontWeight: 800, color: isDarkMode ? "#FFD700" : "#b8860b", marginBottom: 16 }}>
            Rubina's Answer
          </Typography>
          <Typography style={{ color: isDarkMode ? "#e0e0e0" : "#333", lineHeight: 1.8, fontSize: "1rem", whiteSpace: "pre-wrap" }}>
            {reply}
          </Typography>
        </Box>
      )}
    </Container>
  );
};

export default AiPage;
